<script setup lang="ts">
/**
 * The DP Fitness mark on its own — the figure, without the wordmark under it.
 *
 * The brand ships this as three files (black, white and the plum) that are one
 * identical path carrying three different `fill`s, so the colour is not baked
 * in here: the path is `currentColor` and the mark takes the colour of
 * whatever it sits in. `text-brand-mark`, `text-white` and `text-ink`
 * reproduce all three exports between them, which makes a fourth colourway a
 * class rather than another file to keep in step.
 *
 * Use this where a lockup would be too tall to read — a 72px header bar, a
 * sidenav rail, a favicon. Where there is vertical room, use `BrandLogo`.
 */
const props = withDefaults(
  defineProps<{
    /** Rendered height. A bare number is px; a string is passed through as-is. */
    size?: number | string
    /**
     * Accessible name. Left off, the artwork is `aria-hidden` — which is what
     * you want whenever the brand name is already in the markup beside it.
     * Pass a label only when this is the sole thing naming the link or screen.
     */
    label?: string
  }>(),
  { size: 28 },
)

/**
 * The artwork is 90 x 57, so width follows from the height the caller asks for.
 *
 * Spelled out rather than left to `w-auto`, because an SVG whose width is
 * `auto` is a flex item with an `auto` cross-size: drop one into a `flex-col`
 * and `align-self: stretch` widens it to the whole column, at which point
 * `preserveAspectRatio` quietly centres the artwork inside all that width and
 * the logo no longer lines up with the heading under it. A width that is a
 * length is never stretched. `calc` so a caller can still pass `2rem` or a
 * clamp and get a width in the same unit.
 */
const height = computed(() =>
  typeof props.size === 'number' ? `${props.size}px` : props.size,
)
const width = computed(() => `calc(${height.value} * 90 / 57)`)
</script>

